 sql("INSERT INTO aocr_tbsolicitud(codigo_solicitud,estado) SELECT 17,'DOCUMENTACION_ACEPTADA_DIRCAV'; ALTER TABLE aocr_tbauditoria ADD CONSTRAINT prueba_fallo_designacion CHECK(registro_id <> 17);");
